import {observe,actions} from './corner-policy';
import type {CubeData,JevRequest,JevResponse} from '../../src/lib/types';
export {actions};
export type Variant='recognition'|'measured';
const ring=['F','R','B','L'];
const options=Object.fromEntries(['green','red','blue','orange','mixed'].map(c=>[c,c==='mixed'?'The two corner sticker colors differ.':`Both corner stickers are ${c}.`]));
export async function decide(state:CubeData,variant:Variant,history:string[],ask:(r:JevRequest)=>Promise<JevResponse>){
 const observation=observe(state);let pairs:Record<string,string>;
 if(variant==='recognition'){
  const result=await ask({model:'jev-1.13.0',state:{sides:observation.sides},questions:Object.fromEntries(ring.map(f=>['pair_'+f,{type:'choice',instructions:`Read only sides.${f}.cornerStickers. If their two colors match, return that shared color. Otherwise return mixed. Ignore the center color.`,criteria:options}]))});
  pairs=Object.fromEntries(ring.map(f=>[f,result.answers['pair_'+f].choice]));
 }else pairs=Object.fromEntries(ring.map(f=>{const c=observation.sides[f].cornerStickers;return [f,c[0].color===c[1].color?c[0].color:'mixed'];}));
 // Count observed/model-reported categories without repairing them.
 const pairCount=Object.values(pairs).filter(x=>x!=='mixed').length;
 const criteria:Record<string,string>={
  done:'All four pair colors already equal their own side centers. Corners are solved.',
  U:'Four matching pairs exist but need alignment. Move pair colors F→L, L→B, B→R, R→F. Choose if every moved pair will match its destination center.',
  "U'":'Four matching pairs exist but need alignment. Move pair colors F→R, R→B, B→L, L→F. Choose if every moved pair will match its destination center.',
  U2:'Four matching pairs exist but need alignment. Swap pair colors F/B and R/L. Choose if every moved pair will match its destination center.',
  ...Object.fromEntries(ring.map((f,i)=>['T@'+f,`Choose if pairCount=0, OR pairCount=1 and pairColors.${ring[(i+3)%4]} is not mixed. Hold the existing matching pair on local LEFT (${ring[(i+3)%4]}); T swaps the opposite right corners. With no pair, this creates one. Front ${f}. Do not use when pairCount=4.`]))
 };
 const result=await ask({model:'jev-1.13.0',state:{pairColors:pairs,pairCount,centers:Object.fromEntries(ring.map(f=>[f,observation.sides[f].center])),recentActions:history.slice(-2)},questions:{action:{type:'choice',instructions:'Place all upper corners against their matching side centers. pairColors gives the shared color of each side corner pair, or mixed. Matching pair does not mean matched to its center. Apply the general pattern rules in the options. Upper edges can move; all routines restore lower layers and orientation.',criteria}}});
 return result.answers.action.choice;
}

sources.corner-screen-v2:
import {readFileSync,writeFileSync} from 'node:fs';
import {createRun} from '../../src/server/runner';
import {evaluate,budget} from '../../src/server/jev';
import {db,saveRun,getRun} from '../../src/server/store';
import {apply,facts,hash} from '../../src/lib/cube';
import {actions,decide,type Variant} from './corner-policy-v2';
const dir='experiments/efficiency-v1/round2',split='efficiency-corners-v1';
const phase=process.argv[2]??'development';if(!['development','validation'].includes(phase))throw Error('Unknown phase');
const variants:Variant[]=phase==='development'?['recognition','measured']:[process.argv[3] as Variant];
if(variants.some(v=>!['recognition','measured'].includes(v)))throw Error('Choose frozen candidate');
const fixtures=JSON.parse(readFileSync('experiments/efficiency-v1/corner-fixtures.json','utf8')).filter((f:any)=>f.split===phase);
const usage=()=>db.query("SELECT COUNT(*) requests,COALESCE(SUM(amount),0) cost FROM ledger l JOIN runs r ON l.run_id=r.id WHERE json_extract(r.json,'$.split')=?").get(split) as {requests:number;cost:number};
writeFileSync(`${dir}/${phase}-started.json`,JSON.stringify({at:new Date().toISOString(),variants,budgetBefore:budget(),limits:{studyDollars:.03,studyRequests:250,concurrency:2,caseMs:120000,caseActions:6,caseTurns:40},sources:Object.fromEntries(['corner-policy','corner-policy-v2','corner-screen-v2','corner-fixtures'].map(f=>[f,readFileSync(`scripts/efficiency-v1/${f}.ts`,'utf8')]))},null,2),{flag:'wx'});
const rows:any[]=[];const persist=()=>writeFileSync(`${dir}/${phase}-results.json`,JSON.stringify({phase,usage:usage(),rows},null,2));
const jobs=variants.flatMap(variant=>fixtures.map((fixture:any)=>({variant,fixture})));let cursor=0;
async function attempt({variant,fixture}:any){
 const run=await createRun('','skills',split);run.state=fixture.state;run.status='ready';saveRun(run);
 const row:any={id:fixture.id,variant,runId:run.id,before:fixture.state,steps:[],status:'running',turns:0,ceiling:fixture.labels.turnCeiling};rows.push(row);persist();
 const start=Date.now();let state=fixture.state;const history:string[]=[];let correctStop=false;
 try{for(let i=0;i<6;i++){
  const step:any={before:state,exchanges:[]};row.steps.push(step);
  const choice=await decide(state,variant,history,async(body)=>{let exchange:any;
  for(let retry=0;retry<3;retry++){
   const u=usage();if(u.cost+.002688>.03||u.requests>=250||budget().reservedAndSpent+.002688>9)throw Error('Budget/request cap');
   if(Date.now()-start>=120000)throw Error('Time cap');
   try{exchange=await evaluate(run.id,structuredClone(body),AbortSignal.timeout(Math.max(1,120000-(Date.now()-start))),{maxAttempts:1});break;}
   catch(e){row.transportErrors??=[];row.transportErrors.push(String(e));persist();if(retry===2||!/(HTTP (429|5\d\d)|network)/i.test(String(e)))throw e;await new Promise(r=>setTimeout(r,1000*2**retry));}
  }
  step.exchanges.push(exchange);persist();return exchange.response;
  });const alg=actions[choice];step.choice=choice;step.alg=alg;
  if(choice==='done'){correctStop=facts(state).cornersPlaced;row.status=correctStop?'done':'premature-done';break;}
  const count=alg.split(/\s+/).length;if(row.turns+count>40){row.status='turn-cap';break;}
  state=await apply(state,alg);row.turns+=count;history.push(choice);step.after=state;
  if(!facts(state).middle||!facts(state).topCross||!facts(state).topOriented)throw Error('Preservation failed');
  run.state=state;run.history=history;saveRun({...getRun(run.id),state,history,turns:row.turns});persist();
 }
 if(row.status==='running')row.status='action-cap';
 }catch(e){row.status='error';row.error=String(e);}
 row.after=state;row.completed=facts(state).cornersPlaced;row.passed=correctStop&&row.turns<=row.ceiling;row.elapsedMs=Date.now()-start;
 saveRun({...getRun(run.id),state,history,turns:row.turns,status:'stopped',reason:`Corner ${phase}: ${row.status}`});persist();
 console.log(variant,fixture.id,row.status,row.turns,'pass',row.passed);
}
await Promise.all(Array.from({length:2},async()=>{while(cursor<jobs.length)await attempt(jobs[cursor++]);}));
console.log(JSON.stringify({usage:usage(),scores:variants.map(v=>({variant:v,passed:rows.filter(r=>r.variant===v&&r.passed).length,n:rows.filter(r=>r.variant===v).length}))}));

